type Exp = u128;
struct BlockSimulator {
    pub left_tape: Vec<BlockSymbol>,
    pub right_tape: Vec<BlockSymbol>,
    pub state: HigherState,
    pub base_steps: u128,
    pub self_steps: u64,
}
impl fmt::Display for BlockSymbol {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use BlockSymbol::*;
        let s0 = match *self {
            Run(t, _) => &format!("{:?}", t),
            _ => &format!("{:?}", self),
        };
        let s_exp = match *self {
            Run(_, n) => if n == 1 { "" } else { &format!("^{}", n) }
            _ => "",
        };
        write!(f, "{}{}", s0, s_exp)
    }
}

// End of customizable code

impl BlockSimulator {
    pub fn new() -> Self {
        use BlockSymbol::*;
        use RunSymbolType::*;
        Self {
            left_tape: vec![L, D],
            right_tape: vec![R, Run(W, 1)],
            state: HigherState::Right,
            base_steps: 10,
            self_steps: 0
        }
    }

    pub fn step(&mut self) -> Result<(), SimError> {
        let new_base_steps = self.basic_step()?;
        self.base_steps = self.base_steps.checked_add(new_base_steps.into()).unwrap();
        self.self_steps += 1;
        Ok(())
    }

    pub fn parse_right_tape_exponents(&self) -> Option<(Exp, Exp)> {
        use BlockSymbol::*;
        use RunSymbolType::*;
        match self.right_tape.as_slice() {
            [R] => Some((0,0)),
            [R, Run(W, m)] => Some((*m, 0)),
            [R, Run(V, n)] => Some((0, *n)),
            [R, Run(V, n), Run(W, m)] => Some((*m, *n)),
            _ => None,
        }
    }
}

#[derive(Copy, Clone, PartialEq, Eq)]
enum LeftReturningHead { Left, C, U, QP}

impl fmt::Display for LeftReturningHead {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use LeftReturningHead::*;
        write!(f, "{}", match &self {
            Left => "<",
            C => "c",
            U => "U",
            QP => "QP",
        })
    }
}

type RightExp = u32;

#[derive(Copy, Clone, PartialEq, Eq)]
struct RightTapeOutcome {
    head: LeftReturningHead,
    m: RightExp,
    n: RightExp,
}

impl fmt::Display for RightTapeOutcome {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{} {},{}", self.head, self.m, self.n)
    }
}

fn calculate_right_tape_outcome(m0: Exp, n0: Exp, initial_state: HigherState) -> RightTapeOutcome {
    use BlockSymbol::*;
    use RunSymbolType::*;
    use HigherState::*;

    let mut sim = BlockSimulator {
        left_tape: vec![],
        right_tape: vec![R],
        state: initial_state,
        base_steps: 0,
        self_steps: 0
    };

    if n0 > 0 {
        sim.right_tape.push(Run(V, n0));
    }
    if m0 > 0 {
        sim.right_tape.push(Run(W, m0));
    }

    loop {
        let head = match (&sim.state, sim.left_tape.as_slice()) {
            (Left, []) => Some(LeftReturningHead::Left),
            (LeftC, []) => Some(LeftReturningHead::C),
            (LeftC, [U]) => Some(LeftReturningHead::U),
            (LeftC, [Q, P]) => Some(LeftReturningHead::QP),
            _ => None,
        };
        if let Some(head) = head {
            let (m, n) = sim.parse_right_tape_exponents().unwrap();
            return RightTapeOutcome { head, m: m as RightExp, n: n as RightExp };
        }

        sim.step().unwrap();
        // println!("{sim}");
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Hash)]
struct RightRuns {
    /// exponent of W on the right
    m: RightExp,
    /// exponent of V on the right
    n: RightExp
}

use std::collections::HashMap;
struct Memo(HashMap<RightRuns, RightTapeOutcome>);

impl Memo {
    fn new() -> Self {
        Self(HashMap::new())
    }

    fn get_or_calculate(&mut self, state: HigherState, m: RightExp, n: RightExp) -> RightTapeOutcome {
        use LeftReturningHead as LH;
        if state == HigherState::RightA {
            if n == 0 {
                return RightTapeOutcome { head: LH::C, m: 0, n: m };
            } else {
                return RightTapeOutcome { head: LH::Left, m: m+1, n: n-1 };
            }
        }
        if let Some(outcome) = self.0.get(&RightRuns { m, n }) {
            return *outcome;
        }

        assert!(state == HigherState::Right);
        let mut sim = CachedSimulator::new_inner(m, n);
        sim.basic_step();
        let outcome = loop {
            if let Some(outcome) = sim.try_parse_outcome() {
                break outcome;
            } else {
                sim.step(self);
            }
        };
        self.0.insert(RightRuns { m, n }, outcome);
        outcome
    }
}

#[allow(non_snake_case)]
struct CachedSimulator {
    left_tape: Vec<BlockSymbol>,
    right_W: RightExp,
    right_V: RightExp,
    state: HigherState,
    self_steps: u64,
}

impl CachedSimulator {
    pub fn new_outer() -> Self {
        use BlockSymbol::*;

        Self {
            left_tape: vec![L, D],
            right_W: 1,
            right_V: 0,
            state: HigherState::Right,
            self_steps: 0,
        }
    }

    pub fn new_inner(m0: RightExp, n0: RightExp) -> Self {
        Self {
            left_tape: vec![],
            right_W: m0,
            right_V: n0,
            state: HigherState::Right,
            self_steps: 0,
        }
    }

    pub fn step(&mut self, memo: &mut Memo) {
        if self.state == HigherState::Right || self.state == HigherState::RightA {
            let RightTapeOutcome { head, m: m_out, n: n_out } = memo.get_or_calculate(self.state, self.right_W, self.right_V);
            self.right_W = m_out;
            self.right_V = n_out;

            use LeftReturningHead::*;
            use BlockSymbol as B;
            match head {
                Left => self.state = HigherState::Left,
                C => self.state = HigherState::LeftC,
                U => {
                    self.state = HigherState::LeftC;
                    self.left_tape.push(B::U);
                },
                QP => {
                    self.state = HigherState::LeftC;
                    self.left_tape.extend_from_slice(&[B::Q, B::P]);
                }
            }
            self.self_steps += 1;
        } else {
            self.basic_step();
        }
    }

    fn basic_step(&mut self) {
        use HigherState::*;
        use BlockSymbol::*;
        use RunSymbolType::*;
        match (
            &self.state,
            self.left_tape.as_slice(),
            self.right_W,
            self.right_V
        ) {
            // > W -> U >
            (Right, _, 1.., _) => {
                self.right_W -= 1;
                self.left_tape.push(U);
            }
            // > V -> < V
            (Right, _, 0, 1..) => {
                self.state = Left;
            }
            // > R -> < R
            (Right, _, 0, 0) => {
                self.state = Left;
            }
            // a> W -> W a>
            (RightA, _, 1.., _) => {
                self.right_W -= 1;
                add_or_merge_run(&mut self.left_tape, W, 1);
            }
            // a> V -> W >
            (RightA, _, 0, 1..) => {
                self.state = Right;
                self.right_V -= 1;
                add_or_merge_run(&mut self.left_tape, W, 1u128);
            }
            // a> R -> <c R
            (RightA, _, 0, 0) => {
                self.state = LeftC;
            }
            // U < -> D >
            (Left, [.., U], _, _) => {
                self.state = Right;
                self.left_tape.pop();
                self.left_tape.push(D);
            }
            // D < -> W a>
            (Left, [.., D], _, _) => {
                self.state = RightA;
                self.left_tape.pop();
                add_or_merge_run(&mut self.left_tape, W, 1u128);
            }
            // W < -> < W
            (Left, [.., Run(W, exp)], _, _) => {
                let n = *exp;
                self.left_tape.pop();
                self.right_W += n as RightExp;
            }
            // L < -> L D >
            (Left, [.., L], _, _) => {
                self.state = Right;
                self.left_tape.push(D);
            }
            // L P < -> L P U >
            (Left, [.., L, P], _, _) => {
                self.state = Right;
                self.left_tape.push(U);
            }
            // W P < -> P < W
            (Left, [.., Run(W, exp), P], _, _) => {
                let n = *exp;
                self.left_tape.pop();
                self.left_tape.pop();
                self.left_tape.push(P);
                self.right_W += n as RightExp;
            }
            // D P < -> P W a>
            (Left, [.., D, P], _, _) => {
                self.state = RightA;
                self.left_tape.pop();
                self.left_tape.pop();
                self.left_tape.push(P);
                self.left_tape.push(Run(W, 1u128));
            }
            // Q P < -> U <c
            (Left, [.., Q, P], _, _) => {
                self.state = LeftC;
                self.left_tape.pop();
                self.left_tape.pop();
                self.left_tape.push(U);
            }
            // W <c -> <c V
            (LeftC, [.., Run(W, exp)], _, _) => {
                assert!(self.right_W == 0);
                let n = *exp;
                self.left_tape.pop();
                self.right_V += n as RightExp;
            }
            // D <c -> < W
            (LeftC, [.., D], _, _) => {
                self.state = Left;
                self.left_tape.pop();
                self.right_W += 1;
            }
            // P U <c -> P W a>
            (LeftC, [.., P, U], _, _) => {
                self.state = RightA;
                self.left_tape.pop();
                self.left_tape.push(Run(W, 1u128));
            }
            // W U <c -> W W a>
            (LeftC, [.., Run(W, _), U], _, _) => {
                self.state = RightA;
                self.left_tape.pop();
                self.left_tape.push(Run(W, 1u128));
            }
            // D U <c -> W U >
            (LeftC, [.., D, U], _, _) => {
                self.state = Right;
                self.left_tape.pop();
                self.left_tape.pop();
                add_or_merge_run(&mut self.left_tape, W, 1u128);
                self.left_tape.push(U);
            }
            // P U U <c -> D P U >
            (LeftC, [.., P, U, U], _, _) => {
                self.state = Right;
                self.left_tape.pop();
                self.left_tape.pop();
                self.left_tape.pop();
                self.left_tape.push(D);
                self.left_tape.push(P);
                self.left_tape.push(U);
            }
            // U U <c -> Q P U >
            (LeftC, [.., U, U], _, _) => {
                self.state = Right;
                self.left_tape.pop();
                self.left_tape.pop();
                self.left_tape.push(Q);
                self.left_tape.push(P);
                self.left_tape.push(U);
            }
            // L <c -> L P U >
            (LeftC, [.., L], _, _) => {
                self.state = Right;
                self.left_tape.push(P);
                self.left_tape.push(U);
            }
            // L P <c -> L D W W >
            (LeftC, [.., L, P], _, _) => {
                self.state = Right;
                self.left_tape.pop();
                self.left_tape.push(D);
                self.left_tape.push(Run(W, 2u128));
            }
            // U Q P <c -> < W V
            (LeftC, [.., U, Q, P], _, _) => {
                self.state = Left;
                self.left_tape.pop();
                self.left_tape.pop();
                self.left_tape.pop();
                assert!(self.right_W == 0);
                self.right_V += 1;
                self.right_W = 1;
            }
            _ => unimplemented!(),
        }
        self.self_steps += 1;
    }

    fn try_parse_outcome(&self) -> Option<RightTapeOutcome> {
        use HigherState::*;
        use BlockSymbol::*;
        let head = match (&self.state, self.left_tape.as_slice()) {
            (Left, []) => LeftReturningHead::Left,
            (LeftC, []) => LeftReturningHead::C,
            (LeftC, [U]) => LeftReturningHead::U,
            (LeftC, [Q, P]) => LeftReturningHead::QP,
            _ => return None,
        };
        Some(RightTapeOutcome { head, m: self.right_W, n: self.right_V })
    }
}

impl fmt::Display for CachedSimulator {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use colored::*;
        const LEFT_PRINT_THRESHOLD: usize = 100;
        let l_th = LEFT_PRINT_THRESHOLD / 2;
        self.self_steps.fmt(f)?;
        write!(f, ": ")?;
        if self.left_tape.len() <= LEFT_PRINT_THRESHOLD {
            for symb in &self.left_tape {
                write!(f, "{} ", symb)?;
            }
        } else {
            for symb in &self.left_tape[..l_th] {
                write!(f, "{} ", symb)?;
            }
            write!(f, " ...{} terms... ", self.left_tape.len() - LEFT_PRINT_THRESHOLD)?;
            for symb in &self.left_tape[self.left_tape.len() - l_th..] {
                write!(f, "{} ", symb)?;
            }
        }
        match self.state {
            HigherState::Left => write!(f, "{}", "<".red().bold())?,
            HigherState::LeftC => write!(f, "{}", "<c".red().bold())?,
            HigherState::RightA => write!(f, "{}", "a>".red().bold())?,
            HigherState::Right => write!(f, "{}", ">".red().bold())?,
        }
        write!(f, " {}, {}", self.right_W, self.right_V)
    }
}

